                    brtC->VpiFullName(refFullName);
                    brtC->VpiParent(ets);
                    brtC->Actual_typespec(shb);
                    ets->Base_typespec(brtC);
                    baseSyn = nullptr;  // cl0 stays null: no clone, no alias
