                    if (o0->Typespec())
                        n0->Typespec(o0->Typespec());
                    if (o0->Left_expr())
                        n0->Left_expr(o0->Left_expr());
                    if (o0->Right_expr())
                        n0->Right_expr(o0->Right_expr());
                    cl0 = n0;
